// CONCEPTITO MOUNTAIN LAB · MERCADO
// Entrada: 'tick' (250 ms). Salida 1 → LAB: una barra 'mtn_bar' por cada
// segundo GMX completado, o 'mtn_stale' cuando el GMX tiene > 10 s.
//
// Reloj = md_gmx.last[symbol].source_ts (igual que CONCEPTITO_X10_V1).
// Para el boundary T se usa la última cotización con source_ts <= T.
// Un boundary T sólo se procesa cuando llega una cotización con
// source_ts > T (segundo completado): nunca hay look-ahead.
//
// Este nodo NO tiene configuración de simuladores ni base de datos.

const M = context.get('M', 'memory');

if (!M || !M.cfg) {
    node.warn('MOUNTAIN MERCADO: estado M no inicializado (revisar On Start)');
    return null;
}

if (msg.topic !== 'tick') return null;

const K = M.cfg;
const now = Date.now();
const out = [];


// ============================================================
// HELPERS (idénticos a CONCEPTITO_X10_V1)
// ============================================================

function avgLast(n) {
    const a = M.closes;

    if (a.length < n) return null;

    let s = 0;

    for (let i = a.length - n; i < a.length; i++) {
        s += a[i];
    }

    return s / n;
}

function resetSignal() {
    M.closes = [];
    M.sF = null;
    M.sS = null;
    M.lastSign = 0;
    M.smaBuf = [];
}

// Rango causal (t - 30 min, t] sobre GMX MID de 1 s.
function movePut(t, px) {
    const R = M.r30;

    while (R.length && R[0].t <= t - K.moveWindowMs) {
        R.shift();
    }

    if (!R.length) {
        M.r30Since = t;
    }

    R.push({ t: t, px: px });

    let hi = -Infinity;
    let lo = Infinity;

    for (let i = 0; i < R.length; i++) {
        if (R[i].px > hi) hi = R[i].px;
        if (R[i].px < lo) lo = R[i].px;
    }

    M.r30High = hi;
    M.r30Low = lo;
    M.r30Bps = (hi - lo) / px * 10000;
}

function moveWarm(t) {
    return M.r30.length > 0 && t - M.r30Since >= K.moveWindowMs - 1000;
}

function moveWarmSec() {
    if (!M.r30.length || !M.last) return 0;

    return Math.min(
        K.moveWindowMs / 1000,
        Math.round((M.last.t - M.r30Since) / 1000) + 1
    );
}

// Slopes / spread causales contra el segundo exacto t - slopeWindowSec.
function slopes(t, sF, sS) {
    const m = {
        slopeFastBps: null,
        slopeSlowBps: null,
        spreadBps: null,
        spreadBpsLag: null
    };

    if (sF == null || sS == null || !(sF > 0) || !(sS > 0)) return m;

    const lagMs = K.slopeWindowSec * 1000;
    const spread = (sF / sS - 1) * 10000;
    const B = M.smaBuf;

    B.push({ t: t, sF: sF, sS: sS, spread: spread });
    while (B.length > K.slopeWindowSec + 5) B.shift();

    m.spreadBps = spread;

    for (let i = B.length - 1; i >= 0; i--) {
        if (B[i].t === t - lagMs) {
            m.slopeFastBps = (sF / B[i].sF - 1) * 10000;
            m.slopeSlowBps = (sS / B[i].sS - 1) * 10000;
            m.spreadBpsLag = B[i].spread;
            break;
        }
        if (B[i].t < t - lagMs) break;
    }

    return m;
}


// ============================================================
// SEGUNDO STALE / SEGUNDO VÁLIDO
// ============================================================

function onGmxStale(T) {
    if (M.lastBucketT || M.closes.length || M.lastSign !== 0) {
        M.gaps++;
    }

    resetSignal();
    M.lastBucketT = 0;
    M.staleEvents++;

    out.push({ topic: 'mtn_stale', t: T });
}

// b = { t, source_ts, min, max, mid }
function onGmxSecond(b) {
    if (M.lastBucketT && b.t - M.lastBucketT > 1000) {
        resetSignal();
        M.gaps++;
    }

    M.lastBucketT = b.t;
    M.bars++;

    // SMA FAST / SLOW sobre GMX MID (igual que V1).
    M.closes.push(b.mid);
    if (M.closes.length > K.slow) M.closes.shift();

    M.sF = avgLast(K.fast);
    M.sS = avgLast(K.slow);
    M.last = { t: b.t, px: b.mid };

    const sl = slopes(b.t, M.sF, M.sS);

    // MOVEMENT 30 min con datos hasta b.t.
    movePut(b.t, b.mid);
    const warm = moveWarm(b.t);

    // Cruce real SMA35/SMA70 + cooldown cross-to-cross 32 s (igual que V1:
    // todo cruce reinicia el reloj, aun descartado).
    let cross = null;

    if (M.sF != null && M.sS != null) {
        const d = M.sF - M.sS;
        const sg = d > 0 ? 1 : (d < 0 ? -1 : 0);

        if (sg !== 0) {
            const c = (M.lastSign !== 0 && sg !== M.lastSign) ? sg : 0;
            M.lastSign = sg;

            if (c) {
                const prevCrossT = M.lastCrossT || 0;
                const cooldownOk = !prevCrossT || (b.t - prevCrossT >= K.crossCooldownMs);
                M.lastCrossT = b.t;
                M.crosses++;
                if (!cooldownOk) M.crossesCooldown++;

                cross = {
                    side: c > 0 ? 'LONG' : 'SHORT',
                    cooldownOk: cooldownOk,
                    // Fuerza del cruce medida en el segundo de la señal N.
                    crossBps: Math.abs(M.sF / M.sS - 1) * 10000,
                    sF: M.sF,
                    sS: M.sS
                };
            }
        }
    }

    out.push({
        topic: 'mtn_bar',
        bar: {
            t: b.t,
            source_ts: b.source_ts,
            min: b.min,
            max: b.max,
            mid: b.mid,

            sF: M.sF,
            sS: M.sS,
            smaWarm: Math.min(M.closes.length, K.slow),

            range30Bps: M.r30Bps,
            moveWarm: warm,
            moveWarmSec: moveWarmSec(),

            slopeFastBps: sl.slopeFastBps,
            slopeSlowBps: sl.slopeSlowBps,
            spreadBps: sl.spreadBps,
            spreadBpsLag: sl.spreadBpsLag,

            cross: cross
        }
    });
}


// ============================================================
// RELOJ GMX: AS-OF BACKWARD SOBRE SEGUNDOS COMPLETADOS (igual que V1)
// ============================================================

function pumpGmx() {
    const G = global.get('md_gmx', 'memory');
    const z = G && G.last && G.last[K.symbol];

    if (!z) return;

    const s = Number(z.source_ts);
    const mn = Number(z.min);
    const mx = Number(z.max);

    if (!isFinite(s) || !isFinite(mn) || !isFinite(mx) || mn <= 0 || mx <= 0) {
        return;
    }

    if (s <= M.lastGmxSourceTs) return;

    const prev = M.lastGmxQuote;

    if (prev) {
        let T = M.nextGmxBoundary;

        while (T < s) {
            if (T - prev.source_ts > K.gmxMaxAgeMs) {
                onGmxStale(T);
                T = Math.ceil(s / 1000) * 1000;
                break;
            }

            onGmxSecond({
                t: T,
                source_ts: prev.source_ts,
                min: prev.min,
                max: prev.max,
                mid: (prev.min + prev.max) / 2
            });

            T += 1000;
        }

        M.nextGmxBoundary = T;
    } else {
        M.nextGmxBoundary = Math.ceil(s / 1000) * 1000;
    }

    M.lastGmxQuote = { source_ts: s, min: mn, max: mx };
    M.lastGmxSourceTs = s;
}

pumpGmx();

if (now - M.lastStatusAt >= 1000) {
    M.lastStatusAt = now;

    const smaW = Math.min(M.closes.length, K.slow);
    const mw = M.last ? moveWarm(M.last.t) : false;

    node.status({
        fill: (smaW >= K.slow && mw) ? 'green' : 'yellow',
        shape: 'dot',
        text:
            'SMA ' + smaW + '/' + K.slow +
            ' · MOV ' + (mw ? 'warm' : ('warmup ' + moveWarmSec() + '/' + (K.moveWindowMs / 1000) + 's')) +
            ' · range30 ' + (M.r30Bps == null ? '-' : M.r30Bps.toFixed(1)) + ' bps' +
            ' · cruces ' + M.crosses + ' (cooldown ' + M.crossesCooldown + ')' +
            ' · gaps ' + M.gaps
    });
}

return out.length ? [out] : null;

