// ===== CONCEPTITO MOUNTAIN LAB · MERCADO (estado de señal compartido) =====
// PAPER ONLY. Este nodo NO conoce la configuración de los simuladores.
// Sólo produce, para cada segundo GMX válido, una barra causal:
//   GMX MID as-of backward (source_ts <= t, carry-forward <= 10 s)
//   SMA35 / SMA70 · rango MOVEMENT 30 min (bps) · cruce real + cooldown 32 s
//   slopes SMA35/SMA70 vs t-5s y spread/spreadLag (para ESCAPE_DIR)
// Aplicar una configuración en el LAB nunca toca este estado: no hay
// reset de SMA ni nuevo warmup. Redeployar SÓLO el nodo LAB tampoco.

const K = {
    symbol: 'ZEC',
    fast: 35,
    slow: 70,
    crossCooldownMs: 32000,
    gmxMaxAgeMs: 10000,
    moveWindowMs: 30 * 60000,
    slopeWindowSec: 5
};

const M = {
    cfg: K,

    lastBucketT: 0,
    lastGmxSourceTs: 0,
    lastGmxQuote: null,
    nextGmxBoundary: 0,
    gaps: 0,
    staleEvents: 0,

    closes: [],
    sF: null,
    sS: null,
    lastSign: 0,
    lastCrossT: 0,
    last: null,

    smaBuf: [],

    r30: [],
    r30Since: 0,
    r30High: null,
    r30Low: null,
    r30Bps: null,

    crosses: 0,
    crossesCooldown: 0,
    bars: 0,
    lastStatusAt: 0
};

context.set('M', M, 'memory');

node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'MOUNTAIN LAB · MERCADO · esperando GMX'
});

func:
// CONCEPTITO MOUNTAIN LAB · LAB
// Entradas: 'tick' · 'mtn_bar' / 'mtn_stale' (MERCADO) · 'mtn_apply' /
//           'mtn_view' (dashboard) · respuestas mysql · 'db_error'
// Salida 1 → mysql (sólo tablas conceptito_lab_*) · Salida 2 → dashboard
//
// PAPER ONLY. Señal N (cruce SMA35/70 del MERCADO) → ejecución N+1 al
// GMX ejecutable de N+1 (LONG entra max / sale min; SHORT entra min /
// sale max), exactamente como CONCEPTITO_X10_V1.
//
// config_version: cada APLICAR crea una versión nueva. Las posiciones
// abiertas conservan la config con la que nacieron; las nuevas usan la
// vigente. Las versiones anteriores sólo se drenan (no abren más).
// Las estadísticas se agregan por (config_version, variante): nunca se
// mezclan trades de versiones distintas.

const ENGINE = 'CONCEPTITO_MOUNTAIN_LAB';
const LAB = 'MOUNTAIN_LAB_V1';
const SYMBOL = 'ZEC';
const T_TRADES = 'conceptito_lab_trades';
const T_CONFIGS = 'conceptito_lab_configs';
const GMX_MAX_AGE_MS = 10000;
const MAX_GRID_CELLS = 64;
const MAX_ROW_BATCH = 40;
const RECENT_MAX = 30;

const L = context.get('L', 'memory');

if (!L || !L.defaultCfg) {
    node.warn(ENGINE + ': estado L no inicializado (revisar On Start)');
    return null;
}

const now = Date.now();
const out = [null, null];


// ============================================================
// HELPERS
// ============================================================

function pad(n, w) {
    return String(n).padStart(w || 2, '0');
}

function dt(t) {
    const d = new Date(t);

    return (
        d.getUTCFullYear() + '-' +
        pad(d.getUTCMonth() + 1) + '-' +
        pad(d.getUTCDate()) + ' ' +
        pad(d.getUTCHours()) + ':' +
        pad(d.getUTCMinutes()) + ':' +
        pad(d.getUTCSeconds()) + '.' +
        pad(d.getUTCMilliseconds(), 3)
    );
}

function r(v, d) {
    return v == null || !isFinite(v) ? null : Number(Number(v).toFixed(d));
}

function num(v) {
    return v == null ? null : Number(v);
}

function fmtNum(v) {
    return String(Number(Number(v).toFixed(4)));
}

function variantKey(mov, risk) {
    return 'MOV' + fmtNum(mov) + '_R' + fmtNum(risk);
}

function simKey(version, variant) {
    return version + '|' + variant;
}

// GMX ejecutable (idéntico a CONCEPTITO_X10_V1).
// q = { t, source_ts, min, max }
function gmxPx(q, side, action) {
    if (
        !q ||
        !isFinite(q.min) ||
        !isFinite(q.max) ||
        !isFinite(q.t) ||
        !isFinite(q.source_ts) ||
        q.source_ts > q.t ||
        q.t - q.source_ts > GMX_MAX_AGE_MS
    ) {
        return null;
    }

    return action === 'ENTRY'
        ? (side === 'LONG' ? q.max : q.min)
        : (side === 'LONG' ? q.min : q.max);
}


// ============================================================
// CONFIGURACIÓN: validación / versiones / simuladores
// ============================================================

function parseList(v) {
    if (Array.isArray(v)) return v.map(Number);
    return String(v == null ? '' : v)
        .split(/[\s,;]+/)
        .filter(function (x) { return x !== ''; })
        .map(Number);
}

function uniqSorted(a) {
    const s = {};
    const res = [];
    a.forEach(function (x) {
        const k = fmtNum(x);
        if (!s[k]) { s[k] = true; res.push(Number(k)); }
    });
    return res.sort(function (x, y) { return x - y; });
}

function bool(v) {
    return v === true || v === 'true' || v === 1 || v === '1' || v === 'on';
}

// Devuelve { ok, cfg } o { ok:false, err }.
function validateCfg(p) {
    const D = L.defaultCfg;
    const errs = [];

    function numIn(name, v, lo, hi) {
        const n = Number(v);
        if (v === '' || v == null || !isFinite(n) || n < lo || n > hi) {
            errs.push(name + ' fuera de rango [' + lo + ', ' + hi + ']');
            return null;
        }
        return n;
    }

    const movList = uniqSorted(parseList(p.movList));
    const riskList = uniqSorted(parseList(p.riskList));

    if (!movList.length || movList.some(function (x) { return !isFinite(x) || x < 0 || x > 2000; })) {
        errs.push('MOVEMENT: lista de números entre 0 y 2000');
    }
    if (!riskList.length || riskList.some(function (x) { return !isFinite(x) || x <= 0 || x > 20; })) {
        errs.push('RISK: lista de números > 0 y <= 20');
    }
    if (movList.length * riskList.length > MAX_GRID_CELLS) {
        errs.push('grilla de ' + (movList.length * riskList.length) + ' celdas > máximo ' + MAX_GRID_CELLS);
    }

    const tpUsd = numIn('TP USD', p.tpUsd, 0.01, 100000);
    let slUsd = numIn('SL USD', p.slUsd, -100000, -0.01);
    const timeoutMin = numIn('timeout', p.timeoutMin, 1, 1440);
    const minCrossBps = numIn('MIN_CROSS_BPS', p.minCrossBps, 0, 1000);
    const spacingMin = numIn('spacing', p.spacingMin, 0, 1440);
    const maxPos = numIn('max posiciones', p.maxPos, 1, 50);
    const escapeArmMfeUsd = numIn('escape arm MFE', p.escapeArmMfeUsd, 0.01, 100000);
    const escapeGivebackUsd = numIn('escape giveback', p.escapeGivebackUsd, 0.01, 100000);

    if (maxPos != null && Math.floor(maxPos) !== maxPos) errs.push('max posiciones debe ser entero');

    if (errs.length) return { ok: false, err: errs.join(' · ') };

    return {
        ok: true,
        cfg: {
            movList: movList,
            riskList: riskList,
            tpUsd: tpUsd,
            slUsd: slUsd,
            timeoutMin: timeoutMin,
            minCrossBps: minCrossBps,
            spacingMin: spacingMin,
            maxPos: maxPos,
            escapeOn: bool(p.escapeOn),
            escapeArmMfeUsd: escapeArmMfeUsd,
            escapeGivebackUsd: escapeGivebackUsd,

            // Fijos de la base del experimento.
            escapeSlopeWindowSec: D.escapeSlopeWindowSec,
            escapeConfirmSec: D.escapeConfirmSec,
            escapeOnlyIfPositive: D.escapeOnlyIfPositive,
            baseExposureUsd: D.baseExposureUsd,
            leverage: D.leverage,
            feeRate: D.feeRate,
            fast: D.fast,
            slow: D.slow,
            crossCooldownSec: D.crossCooldownSec
        }
    };
}

function sameCfg(a, b) {
    return JSON.stringify(a) === JSON.stringify(b);
}

function makeSim(version, cfg, mov, risk) {
    const exposure = cfg.baseExposureUsd * risk;
    const variant = variantKey(mov, risk);

    const snap = {
        lab: LAB,
        symbol: SYMBOL,
        config_version: version,
        variant: variant,
        movement_bps: mov,
        risk_mult: risk,
        exposure_usd: exposure,
        margin_usd: exposure / cfg.leverage,
        cfg: cfg
    };

    return {
        key: simKey(version, variant),
        version: version,
        variant: variant,
        mov: mov,
        risk: risk,
        exposure: exposure,
        margin: exposure / cfg.leverage,
        feeEntry: exposure * cfg.feeRate,
        feeExit: exposure * cfg.feeRate,
        c: cfg,
        snapJson: JSON.stringify(snap),
        draining: false,
        positions: [],
        lastEntryT: 0,
        accepted: 0,
        rej: { move: 0, cross: 0, maxPos: 0, spacing: 0 }
    };
}

function emptyStats() {
    return {
        ops: 0, tp: 0, sl: 0, esc: 0, to: 0,
        gross: 0, fees: 0, net: 0,
        wins: 0, winSum: 0, lossSum: 0
    };
}

function statsFor(key) {
    if (!L.stats[key]) L.stats[key] = emptyStats();
    return L.stats[key];
}

// Activa una versión: crea sus simuladores y pone las anteriores a drenar.
function activate(version, cfg, createdT) {
    Object.keys(L.sims).forEach(function (k) {
        const s = L.sims[k];
        if (s.version !== version) s.draining = true;
    });

    L.versions[version] = { cfg: cfg, createdT: createdT };
    L.active = { version: version, cfg: cfg, createdT: createdT };
    if (version > L.maxVersion) L.maxVersion = version;

    cfg.movList.forEach(function (mov) {
        cfg.riskList.forEach(function (risk) {
            const s = makeSim(version, cfg, mov, risk);
            if (!L.sims[s.key]) L.sims[s.key] = s;
            const le = L.restoredLastEntry[s.key];
            if (le && le > L.sims[s.key].lastEntryT) L.sims[s.key].lastEntryT = le;
        });
    });

    pruneSims();
    L.dirty = true;
}

// Elimina simuladores de versiones viejas que ya no tienen posiciones.
function pruneSims() {
    Object.keys(L.sims).forEach(function (k) {
        const s = L.sims[k];
        if (s.draining && !s.positions.length) delete L.sims[k];
    });
}

function enqueueConfig(version, cfg, createdT) {
    enqueue({
        kind: 'sql',
        tag: 'config',
        sql:
            'INSERT INTO ' + T_CONFIGS +
            ' (lab, config_version, created_ts, config_json) VALUES (?, ?, ?, ?) ' +
            'ON DUPLICATE KEY UPDATE config_json = VALUES(config_json)',
        params: [LAB, version, dt(createdT), JSON.stringify(cfg)]
    });
}


// ============================================================
// PERSISTENCIA (cola + backoff, estilo V1; upsert por lotes)
// ============================================================

const COLS = [
    'lab', 'symbol', 'config_version', 'variant',
    'movement_bps', 'risk_mult', 'exposure_usd', 'margin_usd', 'leverage',
    'tp_usd', 'sl_usd', 'timeout_min',
    'min_cross_bps', 'cross_bps', 'spacing_min', 'max_pos',
    'escape_on', 'escape_arm_mfe_usd', 'escape_giveback_usd',
    'escape_slope_window_sec', 'escape_confirm_sec', 'escape_only_if_positive',
    'fee_rate', 'status', 'slot',
    'signal_ts', 'entry_ts', 'exit_ts', 'side',
    'entry_price', 'exit_price', 'exit_trigger_price', 'qty',
    'sma_fast_entry', 'sma_slow_entry', 'range30_bps_signal',
    'gross_pnl', 'fee_entry', 'fee_exit', 'fees', 'net_pnl',
    'exit_reason', 'duration_seconds', 'mfe_usd', 'mae_usd',
    'config_json'
];

const UPD = [
    'status', 'exit_ts', 'exit_price', 'exit_trigger_price',
    'gross_pnl', 'fee_exit', 'fees', 'net_pnl',
    'exit_reason', 'duration_seconds', 'mfe_usd', 'mae_usd'
];

const UPSERT_SQL =
    'INSERT INTO ' + T_TRADES + ' (' + COLS.join(', ') + ') VALUES ? ' +
    'ON DUPLICATE KEY UPDATE ' +
    UPD.map(function (c) { return c + ' = VALUES(' + c + ')'; }).join(', ');

function enqueue(item) {
    L.q.push(item);

    if (L.q.length > 5000) {
        // Nunca se descartan DDL / restore / configs: sólo filas.
        for (let i = 0; i < L.q.length; i++) {
            if (L.q[i].kind === 'row') {
                L.q.splice(i, 1);
                L.dbDropped++;
                L.dbErr = 'cola DB llena: se descartó la fila más vieja';
                break;
            }
        }
    }
}

function rowOf(p, x) {
    const c = p.c;

    return [
        LAB, SYMBOL, p.version, p.variant,
        p.mov, p.risk, p.exposure, p.margin, c.leverage,
        c.tpUsd, c.slUsd, c.timeoutMin,
        c.minCrossBps, r(p.crossBps, 6), c.spacingMin, c.maxPos,
        c.escapeOn ? 1 : 0, c.escapeArmMfeUsd, c.escapeGivebackUsd,
        c.escapeSlopeWindowSec, c.escapeConfirmSec, c.escapeOnlyIfPositive ? 1 : 0,
        c.feeRate, x ? 'CLOSED' : 'OPEN', p.slot,
        dt(p.signalT), dt(p.entryT), x ? dt(x.t) : null, p.side,
        p.entryPx, x ? r(x.px, 8) : null, x ? x.trigger : null, r(p.qty, 10),
        r(p.sFast, 8), r(p.sSlow, 8), r(p.range30Bps, 4),
        x ? r(x.gross, 4) : null, r(p.feeEntry, 4), x ? r(x.feeExit, 4) : null,
        x ? r(x.fees, 4) : null, x ? r(x.net, 4) : null,
        x ? x.reason : null, x ? x.dur : null,
        x ? r(p.mfe, 4) : null, x ? r(p.mae, 4) : null,
        p.snapJson
    ];
}

function saveRow(p, x) {
    enqueue({ kind: 'row', row: rowOf(p, x) });
}

function isSqlError(m) {
    return /^ER_/.test(m) && !/^ER_LOCK_(WAIT_TIMEOUT|DEADLOCK)/.test(m);
}

function fail(reason) {
    const m = String(reason).slice(0, 240);

    if (m !== L.dbErr || now - L.lastLogAt > 60000) {
        node.warn(ENGINE + ' DB: ' + m);
        L.lastLogAt = now;
    }

    L.dbErrors++;
    L.dbErr = m;
    L.dbOk = false;

    const items = L.inflight && L.inflight.items ? L.inflight.items : [];

    // Fila "veneno" (error SQL, no de conexión): primero se reintenta de a
    // una; si una fila sola sigue fallando se descarta para no trabar la cola.
    if (isSqlError(m) && items.length && items[0].kind === 'row') {
        L.failStreak++;

        if (items.length > 1) {
            L.singleMode = true;
        } else if (L.failStreak >= 5) {
            L.dbDropped++;
            node.warn(ENGINE + ' DB: fila descartada tras 5 errores SQL: ' + m);
            L.inflight = null;
            L.failStreak = 0;
            L.backoff = 0;
            L.nextTry = now + 1000;
            return;
        }
    }

    for (let i = items.length - 1; i >= 0; i--) {
        L.q.unshift(items[i]);
    }

    L.inflight = null;
    L.backoff = Math.min(60000, Math.max(3000, L.backoff * 2));
    L.nextTry = now + L.backoff;
}


// ============================================================
// SIMULACIÓN: abrir / administrar / cerrar
// ============================================================

function freeSlot(sim) {
    const used = {};
    sim.positions.forEach(function (p) { used[p.slot] = true; });
    for (let s = 1; s <= sim.c.maxPos; s++) {
        if (!used[s]) return s;
    }
    return null;
}

function openPos(sim, sig, b) {
    if (sim.positions.length >= sim.c.maxPos) {
        sim.rej.maxPos++;
        return false;
    }

    const px = gmxPx(b, sig.side, 'ENTRY');

    if (px == null) {
        L.counters.openFailGmx++;
        return false;
    }

    const slot = freeSlot(sim);
    if (slot == null) {
        sim.rej.maxPos++;
        return false;
    }

    const p = {
        key: sim.key,
        version: sim.version,
        variant: sim.variant,
        mov: sim.mov,
        risk: sim.risk,
        exposure: sim.exposure,
        margin: sim.margin,
        c: sim.c,
        snapJson: sim.snapJson,

        slot: slot,
        side: sig.side,
        signalT: sig.t,
        entryT: b.t,
        entryPx: px,
        qty: sim.exposure / px,
        crossBps: sig.crossBps,
        sFast: sig.sF,
        sSlow: sig.sS,
        range30Bps: sig.range30Bps,
        feeEntry: sim.exposure * sim.c.feeRate,

        pnl: 0,
        mfe: 0,
        mae: 0,
        giveback: 0,
        lastPx: px,
        lastT: b.t,
        escapeArmed: false,
        escapeConfirm: 0,
        escapeLastT: 0,
        restored: false
    };

    sim.positions.push(p);
    sim.lastEntryT = b.t;
    L.counters.opens++;
    saveRow(p, null);
    return true;
}

function escapeAdverse(p, gross, b) {
    const c = p.c;

    if (!c.escapeOn || !p.escapeArmed) return false;

    if (
        b.slopeFastBps == null ||
        b.slopeSlowBps == null ||
        b.spreadBps == null ||
        b.spreadBpsLag == null
    ) {
        return false;
    }

    if (p.giveback < c.escapeGivebackUsd) return false;
    if (c.escapeOnlyIfPositive && !(gross > 0)) return false;

    if (p.side === 'LONG') {
        return b.slopeFastBps < 0 && b.slopeSlowBps < 0 && b.spreadBps < b.spreadBpsLag;
    }

    return b.slopeFastBps > 0 && b.slopeSlowBps > 0 && b.spreadBps > b.spreadBpsLag;
}

// Prioridad en el mismo segundo: TP > SL > ESCAPE_DIR > TIMEOUT (como V2).
// TP/SL realizan el monto fijo (convención de V1); ESCAPE/TIMEOUT el bruto real.
function managePosition(p, b) {
    const c = p.c;
    const k = p.side === 'LONG' ? 1 : -1;
    const px = gmxPx(b, p.side, 'EXIT');

    if (px == null) return false;

    const gross = k * p.qty * (px - p.entryPx);
    const contiguous = p.escapeLastT > 0 && b.t - p.escapeLastT === 1000;

    p.pnl = gross;
    p.lastPx = px;
    p.lastT = b.t;
    p.escapeLastT = b.t;

    if (gross > p.mfe) p.mfe = gross;
    if (gross < p.mae) p.mae = gross;
    p.giveback = p.mfe - gross;

    if (!p.escapeArmed && p.mfe >= c.escapeArmMfeUsd) p.escapeArmed = true;

    let reason = null;
    let realized = gross;

    if (gross >= c.tpUsd) {
        reason = 'TP';
        realized = c.tpUsd;
    } else if (gross <= c.slUsd) {
        reason = 'SL';
        realized = c.slUsd;
    } else {
        const adverse = escapeAdverse(p, gross, b);
        p.escapeConfirm = adverse ? (contiguous ? p.escapeConfirm + 1 : 1) : 0;

        if (adverse && p.escapeConfirm >= c.escapeConfirmSec) {
            reason = 'ESCAPE_DIR';
        } else if (b.t - p.entryT >= c.timeoutMin * 60000) {
            reason = 'TIMEOUT';
        }
    }

    if (!reason) return false;

    const exitPx = (reason === 'TP' || reason === 'SL')
        ? p.entryPx + k * realized / p.qty
        : px;

    const feeExit = p.exposure * c.feeRate;
    const fees = p.feeEntry + feeExit;
    const net = realized - fees;

    const x = {
        t: b.t,
        px: exitPx,
        trigger: px,
        gross: realized,
        feeExit: feeExit,
        fees: fees,
        net: net,
        reason: reason,
        dur: Math.round((b.t - p.entryT) / 1000)
    };

    saveRow(p, x);

    // Acumula los mismos valores redondeados que se persisten (live == restore).
    const gR = r(realized, 4);
    const fR = r(fees, 4);
    const nR = r(net, 4);

    const S = statsFor(p.key);
    S.ops++;
    if (reason === 'TP') S.tp++;
    else if (reason === 'SL') S.sl++;
    else if (reason === 'ESCAPE_DIR') S.esc++;
    else S.to++;
    S.gross += gR;
    S.fees += fR;
    S.net += nR;
    if (nR > 0) { S.wins++; S.winSum += nR; }
    else if (nR < 0) { S.lossSum += -nR; }

    L.recent.unshift({
        version: p.version,
        variant: p.variant,
        side: p.side,
        entryT: p.entryT,
        exitT: b.t,
        entryPx: p.entryPx,
        exitPx: exitPx,
        reason: reason,
        dur: x.dur,
        mfe: r(p.mfe, 2),
        mae: r(p.mae, 2),
        gross: r(realized, 2),
        fees: r(fees, 2),
        net: r(net, 2)
    });
    if (L.recent.length > RECENT_MAX) L.recent.length = RECENT_MAX;

    return true;
}

function manageAll(b) {
    let closed = 0;

    Object.keys(L.sims).forEach(function (k) {
        const sim = L.sims[k];
        if (!sim.positions.length) return;

        const keep = [];
        for (let i = 0; i < sim.positions.length; i++) {
            const p = sim.positions[i];
            if (b.t > p.entryT && managePosition(p, b)) closed++;
            else keep.push(p);
        }
        sim.positions = keep;
    });

    if (closed) pruneSims();
    return closed;
}


// ============================================================
// BARRAS DEL MERCADO: N+1 → administrar → cruce
// ============================================================

function onCross(b) {
    const cr = b.cross;

    L.counters.crosses++;
    L.lastCross = {
        t: b.t,
        side: cr.side,
        crossBps: r(cr.crossBps, 4),
        cooldownOk: cr.cooldownOk,
        moveWarm: b.moveWarm,
        range30Bps: r(b.range30Bps, 2),
        accepted: 0
    };

    if (!cr.cooldownOk) { L.counters.crossesCooldown++; return; }
    if (!b.moveWarm) { L.counters.crossesWarmup++; return; }
    if (!L.active) return;
    if (L.pend) return; // salvaguarda: nunca duplicar una pendiente

    const v = L.active.version;
    const cfg = L.active.cfg;
    const candidateEntryT = b.t + 1000;
    const keys = [];

    cfg.movList.forEach(function (mov) {
        cfg.riskList.forEach(function (risk) {
            const sim = L.sims[simKey(v, variantKey(mov, risk))];
            if (!sim) return;

            if (!(b.range30Bps >= sim.mov)) { sim.rej.move++; return; }
            if (!(cr.crossBps >= cfg.minCrossBps)) { sim.rej.cross++; return; }
            if (sim.positions.length >= cfg.maxPos) { sim.rej.maxPos++; return; }

            const spacingMs = cfg.spacingMin * 60000;
            if (spacingMs > 0 && sim.lastEntryT && candidateEntryT - sim.lastEntryT < spacingMs) {
                sim.rej.spacing++;
                return;
            }

            sim.accepted++;
            keys.push(sim.key);
        });
    });

    L.lastCross.accepted = keys.length;

    if (!keys.length) return;

    L.counters.signals++;
    L.pend = {
        t: b.t,
        side: cr.side,
        crossBps: cr.crossBps,
        sF: cr.sF,
        sS: cr.sS,
        range30Bps: b.range30Bps,
        keys: keys
    };
}

function onBar(b) {
    L.counters.bars++;

    // 1) Señal pendiente N → entrada N+1 (cada variante, como máximo una).
    if (L.pend) {
        if (b.t === L.pend.t + 1000) {
            const P = L.pend;
            P.keys.forEach(function (k) {
                const sim = L.sims[k];
                // Si entre N y N+1 se aplicó otra versión, la vieja ya no abre.
                if (sim && !sim.draining) openPos(sim, P, b);
            });
        } else {
            L.counters.pendDropped++;
        }
        L.pend = null;
    }

    // 2) Administrar TODAS las posiciones de TODAS las versiones/variantes.
    manageAll(b);

    // 3) Cruce del segundo (señal N).
    if (b.cross) onCross(b);

    L.dirty = true;
}


// ============================================================
// ESTADO PARA EL DASHBOARD
// ============================================================

function cellOf(version, cfg, mov, risk) {
    const variant = variantKey(mov, risk);
    const key = simKey(version, variant);
    const S = L.stats[key] || emptyStats();
    const sim = L.sims[key];
    const exposure = cfg.baseExposureUsd * risk;

    let open = 0;
    let unreal = 0;
    if (sim) {
        open = sim.positions.length;
        sim.positions.forEach(function (p) { unreal += p.pnl || 0; });
    }

    return {
        variant: variant,
        mov: mov,
        risk: risk,
        exposure: exposure,
        feeEntry: r(exposure * cfg.feeRate, 4),
        feeExit: r(exposure * cfg.feeRate, 4),
        feeRoundTrip: r(2 * exposure * cfg.feeRate, 4),
        tpMovePct: r(cfg.tpUsd / exposure * 100, 4),
        slMovePct: r(cfg.slUsd / exposure * 100, 4),

        ops: S.ops, tp: S.tp, sl: S.sl, esc: S.esc, to: S.to,
        gross: r(S.gross, 2),
        fees: r(S.fees, 2),
        net: r(S.net, 2),
        netPerTrade: S.ops ? r(S.net / S.ops, 4) : null,
        winPct: S.ops ? r(S.wins / S.ops * 100, 2) : null,
        profitFactor: S.lossSum > 0 ? r(S.winSum / S.lossSum, 4) : null,
        pfInfinite: S.lossSum === 0 && S.winSum > 0,
        expectancyBps: S.ops ? r(S.net / S.ops / exposure * 10000, 4) : null,

        open: open,
        unrealized: r(unreal, 2),
        lastEntryT: sim ? (sim.lastEntryT || null) : null,
        accepted: sim ? sim.accepted : null,
        rej: sim ? sim.rej : null
    };
}

function matrixOf(version) {
    const V = L.versions[version];
    if (!V) return null;
    const cfg = V.cfg;

    const cells = [];
    cfg.movList.forEach(function (mov) {
        cfg.riskList.forEach(function (risk) {
            cells.push(cellOf(version, cfg, mov, risk));
        });
    });

    return {
        version: version,
        active: !!(L.active && L.active.version === version),
        createdT: V.createdT,
        cfg: cfg,
        cells: cells
    };
}

function versionList() {
    const vs = {};
    Object.keys(L.versions).forEach(function (v) { vs[v] = true; });
    Object.keys(L.stats).forEach(function (k) { vs[k.split('|')[0]] = true; });

    return Object.keys(vs).map(Number).sort(function (a, b) { return b - a; }).slice(0, 50).map(function (v) {
        let ops = 0;
        let net = 0;
        Object.keys(L.stats).forEach(function (k) {
            if (Number(k.split('|')[0]) === v) { ops += L.stats[k].ops; net += L.stats[k].net; }
        });
        let open = 0;
        Object.keys(L.sims).forEach(function (k) {
            if (L.sims[k].version === v) open += L.sims[k].positions.length;
        });
        const V = L.versions[v];
        return {
            version: v,
            active: !!(L.active && L.active.version === v),
            createdT: V ? V.createdT : null,
            known: !!V,
            ops: ops,
            net: r(net, 2),
            open: open
        };
    });
}

function state() {
    const b = L.lastBar;
    const view = L.viewVersion != null && L.versions[L.viewVersion]
        ? L.viewVersion
        : (L.active ? L.active.version : null);

    let openTotal = 0;
    Object.keys(L.sims).forEach(function (k) { openTotal += L.sims[k].positions.length; });

    return {
        engine: ENGINE,
        lab: LAB,
        phase: L.phase,
        t: b ? b.t : null,

        market: b ? {
            t: b.t,
            mid: r(b.mid, 6),
            sF: r(b.sF, 6),
            sS: r(b.sS, 6),
            smaWarm: b.smaWarm,
            smaNeed: L.defaultCfg.slow,
            range30Bps: r(b.range30Bps, 2),
            moveWarm: b.moveWarm,
            moveWarmSec: b.moveWarmSec,
            slopeFastBps: r(b.slopeFastBps, 3),
            slopeSlowBps: r(b.slopeSlowBps, 3),
            spreadBps: r(b.spreadBps, 3)
        } : null,

        lastCross: L.lastCross,
        active: L.active ? { version: L.active.version, createdT: L.active.createdT, cfg: L.active.cfg } : null,
        viewVersion: view,
        versions: versionList(),
        matrix: view != null ? matrixOf(view) : null,
        openTotal: openTotal,
        pend: L.pend ? { t: L.pend.t, side: L.pend.side, n: L.pend.keys.length } : null,
        counters: L.counters,
        recent: L.recent.slice(0, 20),
        applyResult: L.applyResult,

        db: {
            ok: L.dbOk,
            err: L.dbErr,
            errors: L.dbErrors,
            dropped: L.dbDropped,
            queue: L.q.length + (L.inflight ? L.inflight.items.length : 0),
            saved: L.saved
        }
    };
}

function statusText() {
    if (L.phase !== 'OPERANDO') {
        return {
            fill: 'yellow',
            shape: 'ring',
            text: ENGINE + ' · ' + L.phase + (L.dbErr ? ': ' + L.dbErr.slice(0, 50) : '')
        };
    }

    let open = 0;
    let ops = 0;
    let net = 0;
    Object.keys(L.sims).forEach(function (k) { open += L.sims[k].positions.length; });
    if (L.active) {
        Object.keys(L.stats).forEach(function (k) {
            if (Number(k.split('|')[0]) === L.active.version) { ops += L.stats[k].ops; net += L.stats[k].net; }
        });
    }

    const b = L.lastBar;
    const warm = b && b.smaWarm >= L.defaultCfg.slow && b.moveWarm;

    return {
        fill: warm ? 'green' : 'yellow',
        shape: 'dot',
        text:
            'v' + (L.active ? L.active.version : '-') +
            ' · ' + (L.active ? L.active.cfg.movList.length * L.active.cfg.riskList.length : 0) + ' variantes' +
            ' · abiertas ' + open +
            ' · ops ' + ops + ' · neto ' + net.toFixed(2) +
            (warm ? '' : ' · mercado en warmup') +
            ' · DB cola ' + (L.q.length + (L.inflight ? L.inflight.items.length : 0))
    };
}


// ============================================================
// ERROR DB
// ============================================================

if (msg.topic === 'db_error' || msg.error) {
    if (L.inflight && msg.mtnBatch === L.inflight.id) {
        fail((msg.error && msg.error.message) || 'error DB');
    }
    return null;
}


// ============================================================
// RESPUESTAS MYSQL
// ============================================================

if (msg.mtnKind) {
    if (!L.inflight || msg.mtnBatch !== L.inflight.id) return null;

    const kind = L.inflight.kind;
    const items = L.inflight.items;

    L.inflight = null;
    L.backoff = 0;
    L.dbOk = true;
    L.dbErr = '';
    L.failStreak = 0;
    L.singleMode = false;

    if (kind === 'ddl') {
        L.phase = 'RESTAURANDO';
        node.status(statusText());
        return null;
    }

    if (kind === 'restore') {
        const sets = (Array.isArray(msg.payload) ? msg.payload : []).filter(Array.isArray);
        const cfgRows = sets[0] || [];
        const opens = sets[1] || [];
        const agg = sets[2] || [];
        const lastEntries = sets[3] || [];
        const recent = sets[4] || [];

        L.sims = {};
        L.stats = {};
        L.versions = {};
        L.restoredLastEntry = {};
        L.maxVersion = 0;
        L.pend = null;

        cfgRows.forEach(function (row) {
            let cfg = null;
            try { cfg = JSON.parse(row.config_json); } catch (e) { cfg = null; }
            const v = Number(row.config_version);
            if (cfg && cfg.movList && cfg.riskList) {
                L.versions[v] = { cfg: cfg, createdT: row.created_ms == null ? null : Number(row.created_ms) };
            }
            if (v > L.maxVersion) L.maxVersion = v;
        });

        agg.forEach(function (a) {
            const v = Number(a.config_version);
            if (v > L.maxVersion) L.maxVersion = v;
            L.stats[simKey(v, a.variant)] = {
                ops: Number(a.ops || 0),
                tp: Number(a.tp || 0),
                sl: Number(a.sl || 0),
                esc: Number(a.esc || 0),
                to: Number(a.tmo || 0),
                gross: num(a.gross) || 0,
                fees: num(a.fees) || 0,
                net: num(a.net) || 0,
                wins: Number(a.wins || 0),
                winSum: num(a.win_sum) || 0,
                lossSum: num(a.loss_sum) || 0
            };
        });

        lastEntries.forEach(function (e) {
            const v = Number(e.config_version);
            if (v > L.maxVersion) L.maxVersion = v;
            L.restoredLastEntry[simKey(v, e.variant)] = Number(e.last_entry_ms) || 0;
        });

        // Versión vigente: la más alta con config guardada; si no hay, v1 default.
        const known = Object.keys(L.versions).map(Number).sort(function (a, b) { return b - a; });
        if (known.length) {
            const v = known[0];
            activate(v, L.versions[v].cfg, L.versions[v].createdT);
        } else {
            const v = L.maxVersion + 1;
            const cfg = JSON.parse(JSON.stringify(L.defaultCfg));
            activate(v, cfg, now);
            enqueueConfig(v, cfg, now);
        }

        // Posiciones OPEN: cada una con la config con la que nació.
        let restored = 0;
        opens.forEach(function (op) {
            const v = Number(op.config_version);
            let snap = null;
            try { snap = JSON.parse(op.config_json); } catch (e) { snap = null; }

            const c = {
                tpUsd: num(op.tp_usd),
                slUsd: num(op.sl_usd),
                timeoutMin: num(op.timeout_min),
                minCrossBps: num(op.min_cross_bps),
                spacingMin: num(op.spacing_min),
                maxPos: Number(op.max_pos),
                escapeOn: Number(op.escape_on) === 1,
                escapeArmMfeUsd: num(op.escape_arm_mfe_usd),
                escapeGivebackUsd: num(op.escape_giveback_usd),
                escapeSlopeWindowSec: Number(op.escape_slope_window_sec),
                escapeConfirmSec: Number(op.escape_confirm_sec),
                escapeOnlyIfPositive: Number(op.escape_only_if_positive) === 1,
                baseExposureUsd: snap && snap.cfg ? snap.cfg.baseExposureUsd : L.defaultCfg.baseExposureUsd,
                leverage: num(op.leverage),
                feeRate: num(op.fee_rate),
                fast: snap && snap.cfg ? snap.cfg.fast : L.defaultCfg.fast,
                slow: snap && snap.cfg ? snap.cfg.slow : L.defaultCfg.slow,
                crossCooldownSec: snap && snap.cfg ? snap.cfg.crossCooldownSec : L.defaultCfg.crossCooldownSec,
                movList: snap && snap.cfg ? snap.cfg.movList : [num(op.movement_bps)],
                riskList: snap && snap.cfg ? snap.cfg.riskList : [num(op.risk_mult)]
            };

            const key = simKey(v, op.variant);
            let sim = L.sims[key];
            if (!sim) {
                const vc = L.versions[v] ? L.versions[v].cfg : c;
                sim = makeSim(v, vc, num(op.movement_bps), num(op.risk_mult));
                sim.draining = !(L.active && L.active.version === v);
                L.sims[key] = sim;
            }

            const usedSlot = {};
            sim.positions.forEach(function (p) { usedSlot[p.slot] = true; });
            let slot = Number(op.slot);
            if (!(slot >= 1) || usedSlot[slot]) {
                slot = 1;
                while (usedSlot[slot]) slot++;
            }

            const entryT = Number(op.entry_ms);
            sim.positions.push({
                key: key,
                version: v,
                variant: op.variant,
                mov: num(op.movement_bps),
                risk: num(op.risk_mult),
                exposure: num(op.exposure_usd),
                margin: num(op.margin_usd),
                c: c,
                snapJson: op.config_json,

                slot: slot,
                side: op.side,
                signalT: op.signal_ms == null ? entryT - 1000 : Number(op.signal_ms),
                entryT: entryT,
                entryPx: num(op.entry_price),
                qty: num(op.qty),
                crossBps: num(op.cross_bps),
                sFast: num(op.sma_fast_entry),
                sSlow: num(op.sma_slow_entry),
                range30Bps: num(op.range30_bps_signal),
                feeEntry: num(op.fee_entry),

                // MFE/estado de escape no se persisten mientras la fila está
                // OPEN: tras restart/deploy la protección se rearma desde cero.
                pnl: 0,
                mfe: 0,
                mae: 0,
                giveback: 0,
                lastPx: num(op.entry_price),
                lastT: entryT,
                escapeArmed: false,
                escapeConfirm: 0,
                escapeLastT: 0,
                restored: true
            });

            if (entryT > sim.lastEntryT) sim.lastEntryT = entryT;
            restored++;
        });

        L.recent = recent.map(function (x) {
            return {
                version: Number(x.config_version),
                variant: x.variant,
                side: x.side,
                entryT: Number(x.entry_ms),
                exitT: Number(x.exit_ms),
                entryPx: num(x.entry_price),
                exitPx: num(x.exit_price),
                reason: x.exit_reason,
                dur: Number(x.duration_seconds),
                mfe: num(x.mfe_usd),
                mae: num(x.mae_usd),
                gross: num(x.gross_pnl),
                fees: num(x.fees),
                net: num(x.net_pnl)
            };
        });

        L.phase = 'OPERANDO';
        L.dirty = true;

        node.log(
            ENGINE + ': operando · config v' + L.active.version +
            ' · versiones conocidas ' + Object.keys(L.versions).length +
            ' · OPEN restauradas ' + restored +
            ' · celdas con historial ' + Object.keys(L.stats).length
        );

        node.status(statusText());
        return null;
    }

    if (kind === 'rows') L.saved += items.length;
    else L.saved++;

    return null;
}


// ============================================================
// BARRAS DEL MERCADO
// ============================================================

if (msg.topic === 'mtn_bar' && msg.bar) {
    L.lastBar = msg.bar;
    if (L.phase === 'OPERANDO') onBar(msg.bar);
    else L.dirty = true;
    return null;
}

if (msg.topic === 'mtn_stale') {
    L.counters.staleEvents++;
    if (L.pend) {
        // N+1 stale: nunca se fabrica una entrada con una cotización futura.
        L.pend = null;
        L.counters.pendDropped++;
    }
    L.dirty = true;
    return null;
}


// ============================================================
// DASHBOARD: APLICAR / VER VERSIÓN
// ============================================================

if (msg.topic === 'mtn_apply') {
    let res;

    if (L.phase !== 'OPERANDO' || !L.active) {
        res = { ok: false, msg: 'el LAB todavía no está operando (fase ' + L.phase + ')' };
    } else {
        const v = validateCfg(msg.payload || {});

        if (!v.ok) {
            res = { ok: false, msg: v.err };
        } else if (sameCfg(v.cfg, L.active.cfg)) {
            res = { ok: false, msg: 'sin cambios respecto de v' + L.active.version };
        } else {
            const version = L.maxVersion + 1;
            activate(version, v.cfg, now);
            enqueueConfig(version, v.cfg, now);
            L.viewVersion = version;
            res = { ok: true, msg: 'config v' + version + ' activa · las abiertas conservan su versión', version: version };

            node.log(ENGINE + ': APLICAR → config v' + version + ' ' + JSON.stringify(v.cfg));
        }
    }

    res.t = now;
    L.applyResult = res;
    L.dirty = true;
    L.lastEmit = 0;
    return null;
}

if (msg.topic === 'mtn_view') {
    const v = Number(msg.payload && msg.payload.version);
    L.viewVersion = isFinite(v) && L.versions[v] ? v : null;
    L.dirty = true;
    L.lastEmit = 0;
    return null;
}


// ============================================================
// SÓLO TICK
// ============================================================

if (msg.topic !== 'tick') return null;

if (L.inflight && now - L.inflight.sentAt > 30000) {
    fail('timeout: MariaDB no respondió en 30 s');
}

// DDL idempotente y no destructivo (CREATE TABLE IF NOT EXISTS).
if (L.phase === 'INIT' && !L.inflight && !L.q.some(function (i) { return i.kind === 'ddl'; })) {
    L.q.unshift({
        kind: 'ddl',
        sql:
            'CREATE TABLE IF NOT EXISTS ' + T_TRADES + ' (' +
            'id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, ' +
            'lab VARCHAR(32) NOT NULL, ' +
            'symbol VARCHAR(16) NOT NULL, ' +
            'config_version INT UNSIGNED NOT NULL, ' +
            'variant VARCHAR(48) NOT NULL, ' +
            'movement_bps DECIMAL(12,4) NOT NULL, ' +
            'risk_mult DECIMAL(10,4) NOT NULL, ' +
            'exposure_usd DECIMAL(16,4) NOT NULL, ' +
            'margin_usd DECIMAL(16,4) NOT NULL, ' +
            'leverage DECIMAL(8,4) NOT NULL, ' +
            'tp_usd DECIMAL(14,4) NOT NULL, ' +
            'sl_usd DECIMAL(14,4) NOT NULL, ' +
            'timeout_min DECIMAL(10,4) NOT NULL, ' +
            'min_cross_bps DECIMAL(12,4) NOT NULL, ' +
            'cross_bps DECIMAL(14,6) NULL, ' +
            'spacing_min DECIMAL(10,4) NOT NULL, ' +
            'max_pos INT NOT NULL, ' +
            'escape_on TINYINT(1) NOT NULL, ' +
            'escape_arm_mfe_usd DECIMAL(14,4) NULL, ' +
            'escape_giveback_usd DECIMAL(14,4) NULL, ' +
            'escape_slope_window_sec INT NULL, ' +
            'escape_confirm_sec INT NULL, ' +
            'escape_only_if_positive TINYINT(1) NULL, ' +
            'fee_rate DECIMAL(10,6) NOT NULL, ' +
            'status VARCHAR(8) NOT NULL, ' +
            'slot INT NULL, ' +
            'signal_ts DATETIME(3) NULL, ' +
            'entry_ts DATETIME(3) NOT NULL, ' +
            'exit_ts DATETIME(3) NULL, ' +
            'side VARCHAR(5) NOT NULL, ' +
            'entry_price DECIMAL(20,8) NULL, ' +
            'exit_price DECIMAL(20,8) NULL, ' +
            'exit_trigger_price DECIMAL(20,8) NULL, ' +
            'qty DECIMAL(24,10) NULL, ' +
            'sma_fast_entry DECIMAL(20,8) NULL, ' +
            'sma_slow_entry DECIMAL(20,8) NULL, ' +
            'range30_bps_signal DECIMAL(14,4) NULL, ' +
            'gross_pnl DECIMAL(16,4) NULL, ' +
            'fee_entry DECIMAL(14,4) NULL, ' +
            'fee_exit DECIMAL(14,4) NULL, ' +
            'fees DECIMAL(14,4) NULL, ' +
            'net_pnl DECIMAL(16,4) NULL, ' +
            'exit_reason VARCHAR(16) NULL, ' +
            'duration_seconds INT NULL, ' +
            'mfe_usd DECIMAL(16,4) NULL, ' +
            'mae_usd DECIMAL(16,4) NULL, ' +
            'config_json TEXT NULL, ' +
            'created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, ' +
            'PRIMARY KEY (id), ' +
            'UNIQUE KEY uq_lab_trade (lab, config_version, variant, entry_ts), ' +
            'KEY ix_lab_status (lab, symbol, status), ' +
            'KEY ix_lab_version (lab, config_version)' +
            ') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4; ' +

            'CREATE TABLE IF NOT EXISTS ' + T_CONFIGS + ' (' +
            'lab VARCHAR(32) NOT NULL, ' +
            'config_version INT UNSIGNED NOT NULL, ' +
            'created_ts DATETIME(3) NOT NULL, ' +
            'config_json TEXT NOT NULL, ' +
            'PRIMARY KEY (lab, config_version)' +
            ') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
        params: []
    });
    L.phase = 'CREANDO TABLAS';
}

// Restore (después del DDL).
if (
    L.phase === 'RESTAURANDO' &&
    !L.inflight &&
    !L.q.some(function (i) { return i.kind === 'restore'; }) &&
    now >= L.nextTry
) {
    const ms = function (c) {
        return 'TIMESTAMPDIFF(MICROSECOND, \'1970-01-01 00:00:00\', ' + c + ') DIV 1000';
    };

    L.q.unshift({
        kind: 'restore',
        sql:
            'SELECT config_version, ' + ms('created_ts') + ' AS created_ms, config_json ' +
            'FROM ' + T_CONFIGS + ' WHERE lab = ? ORDER BY config_version DESC LIMIT 200; ' +

            'SELECT config_version, variant, movement_bps, risk_mult, exposure_usd, margin_usd, leverage, ' +
            'tp_usd, sl_usd, timeout_min, min_cross_bps, cross_bps, spacing_min, max_pos, ' +
            'escape_on, escape_arm_mfe_usd, escape_giveback_usd, escape_slope_window_sec, ' +
            'escape_confirm_sec, escape_only_if_positive, fee_rate, slot, ' +
            'CASE WHEN signal_ts IS NULL THEN NULL ELSE ' + ms('signal_ts') + ' END AS signal_ms, ' +
            ms('entry_ts') + ' AS entry_ms, side, entry_price, qty, ' +
            'sma_fast_entry, sma_slow_entry, range30_bps_signal, fee_entry, config_json ' +
            'FROM ' + T_TRADES + ' WHERE lab = ? AND symbol = ? AND status = \'OPEN\' ' +
            'ORDER BY entry_ts ASC LIMIT 5000; ' +

            'SELECT config_version, variant, ' +
            'COUNT(*) ops, ' +
            'SUM(exit_reason = \'TP\') tp, ' +
            'SUM(exit_reason = \'SL\') sl, ' +
            'SUM(exit_reason = \'ESCAPE_DIR\') esc, ' +
            'SUM(exit_reason = \'TIMEOUT\') tmo, ' +
            'SUM(gross_pnl) gross, SUM(fees) fees, SUM(net_pnl) net, ' +
            'SUM(net_pnl > 0) wins, ' +
            'SUM(CASE WHEN net_pnl > 0 THEN net_pnl ELSE 0 END) win_sum, ' +
            'SUM(CASE WHEN net_pnl < 0 THEN -net_pnl ELSE 0 END) loss_sum ' +
            'FROM ' + T_TRADES + ' WHERE lab = ? AND symbol = ? AND status = \'CLOSED\' ' +
            'GROUP BY config_version, variant; ' +

            'SELECT config_version, variant, MAX(' + ms('entry_ts') + ') AS last_entry_ms ' +
            'FROM ' + T_TRADES + ' WHERE lab = ? AND symbol = ? ' +
            'GROUP BY config_version, variant; ' +

            'SELECT config_version, variant, side, ' + ms('entry_ts') + ' AS entry_ms, ' +
            ms('exit_ts') + ' AS exit_ms, entry_price, exit_price, exit_reason, duration_seconds, ' +
            'mfe_usd, mae_usd, gross_pnl, fees, net_pnl ' +
            'FROM ' + T_TRADES + ' WHERE lab = ? AND symbol = ? AND status = \'CLOSED\' ' +
            'ORDER BY exit_ts DESC LIMIT ' + RECENT_MAX,

        params: [
            LAB,
            LAB, SYMBOL,
            LAB, SYMBOL,
            LAB, SYMBOL,
            LAB, SYMBOL
        ]
    });
}

// Enviar a MariaDB: un statement (DDL/restore/config) o un lote de filas.
if (!L.inflight && L.q.length && now >= L.nextTry) {
    let items;
    let kind;
    let sql;
    let params;

    if (L.q[0].kind === 'row') {
        const n = L.singleMode ? 1 : MAX_ROW_BATCH;
        items = [];
        while (items.length < n && L.q.length && L.q[0].kind === 'row') {
            items.push(L.q.shift());
        }
        kind = 'rows';
        sql = UPSERT_SQL;
        params = [items.map(function (i) { return i.row; })];
    } else {
        const it = L.q.shift();
        items = [it];
        kind = it.kind;
        sql = it.sql;
        params = it.params;
    }

    L.inflight = { id: ++L.seq, kind: kind, items: items, sentAt: now };

    out[0] = {
        topic: sql,
        payload: params,
        mtnKind: kind,
        mtnBatch: L.inflight.id
    };
}

// Emitir estado al dashboard (máx. 1 vez por segundo).
if (L.dirty && now - L.lastEmit >= 1000) {
    L.dirty = false;
    L.lastEmit = now;

    out[1] = { payload: { mtnLab: state() } };
    node.status(statusText());
}

return (out[0] || out[1]) ? out : null;

