// ===== CONCEPTITO MOUNTAIN LAB · LAB (simuladores + persistencia) =====
// PAPER ONLY. Nunca envía órdenes reales.
// Consume las barras causales del nodo MERCADO (no calcula SMA ni
// MOVEMENT: la configuración de los simuladores está desacoplada del
// estado de mercado). Cada celda MOVEMENT × RISK de cada config_version
// es un simulador paper totalmente independiente.
//
// DEFAULT_CFG sólo se usa si conceptito_lab_configs todavía no tiene
// ninguna versión para este LAB. Después, la configuración vigente se
// cambia en vivo desde el dashboard (APLICAR) y se restaura desde MariaDB.

const DEFAULT_CFG = {
    movList: [20, 40, 60, 80],          // filas: MOVEMENT mínimo (range30 bps)
    riskList: [1.0, 1.5, 2.0, 3.0],     // columnas: multiplicador de exposure
    tpUsd: 25.00,                       // TP fijo en USD (NO escala con exposure)
    slUsd: -75.00,                      // SL fijo en USD (NO escala con exposure)
    timeoutMin: 100,
    minCrossBps: 0,                     // |SMA35/SMA70-1|·1e4 en N (0 = sin filtro)
    spacingMin: 5,                      // separación mínima entre aperturas por variante
    maxPos: 10,                         // posiciones simultáneas por variante
    escapeOn: true,
    escapeArmMfeUsd: 15.00,
    escapeGivebackUsd: 5.00,
    escapeSlopeWindowSec: 5,            // fijo (lo calcula MERCADO)
    escapeConfirmSec: 3,
    escapeOnlyIfPositive: true,

    // Base fija del experimento (se guarda en el snapshot de cada trade)
    baseExposureUsd: 3000,
    leverage: 3,
    feeRate: 0.0005,
    fast: 35,
    slow: 70,
    crossCooldownSec: 32
};

const L = {
    defaultCfg: DEFAULT_CFG,
    phase: 'INIT',

    active: null,          // { version, cfg, createdT }
    versions: {},          // version -> { cfg, createdT }
    maxVersion: 0,
    viewVersion: null,

    sims: {},              // 'v|variant' -> simulador
    stats: {},             // 'v|variant' -> estadísticas CLOSED
    restoredLastEntry: {}, // 'v|variant' -> ms

    pend: null,
    lastBar: null,
    lastCross: null,
    recent: [],

    counters: {
        bars: 0,
        crosses: 0,
        crossesCooldown: 0,
        crossesWarmup: 0,
        signals: 0,
        pendDropped: 0,
        staleEvents: 0,
        opens: 0,
        openFailGmx: 0
    },

    applyResult: null,

    q: [],
    inflight: null,
    seq: 0,
    backoff: 0,
    nextTry: 0,
    saved: 0,
    dbOk: false,
    dbErr: '',
    dbErrors: 0,
    dbDropped: 0,
    failStreak: 0,
    singleMode: false,
    lastLogAt: 0,

    dirty: true,
    lastEmit: 0
};

context.set('L', L, 'memory');

node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'MOUNTAIN LAB · iniciando (DDL + restore MariaDB)'
});
